export interface Env {
  DB: D1Database;
  KV: KVNamespace;
}

export default {
  async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
    const url = new URL(request.url);

    // Standard CORS Headers for API accessibility
    const corsHeaders = {
      "Access-Control-Allow-Origin": "*",
      "Access-Control-Allow-Methods": "GET, HEAD, POST, OPTIONS",
      "Access-Control-Allow-Headers": "Content-Type, Authorization",
    };

    // Handle OPTIONS request for CORS preflight
    if (request.method === "OPTIONS") {
      return new Response(null, {
        headers: corsHeaders,
      });
    }

    // Endpoint: GET /api/health
    if (request.method === "GET" && url.pathname === "/api/health") {
      try {
        // Run simple query to check database connection status
        const stmt = env.DB.prepare("SELECT datetime('now') AS now");
        const result = await stmt.first<{ now: string }>();

        if (!result) {
          throw new Error("No data returned from D1");
        }

        return new Response(
          JSON.stringify({
            status: "ok",
            database: "connected",
            now: result.now,
          }),
          {
            status: 200,
            headers: {
              "Content-Type": "application/json",
              ...corsHeaders,
            },
          }
        );
      } catch (error: any) {
        return new Response(
          JSON.stringify({
            status: "error",
            database: "disconnected",
            error: error.message || "Failed to query D1 database",
          }),
          {
            status: 500,
            headers: {
              "Content-Type": "application/json",
              ...corsHeaders,
            },
          }
        );
      }
    }

    // Endpoint: GET /api/test-repositories
    if (request.method === "GET" && url.pathname === "/api/test-repositories") {
      try {
        const { UserRepository, InvitationRepository, GuestRepository, RsvpRepository } = await import("./db/repositories");

        const userRepo = new UserRepository(env.DB);
        const invRepo = new InvitationRepository(env.DB);
        const guestRepo = new GuestRepository(env.DB);
        const rsvpRepo = new RsvpRepository(env.DB);

        // Test 1: findUserById
        const user = await userRepo.findUserById("user_dummy_1");

        // Test 2: findInvitationBySlug
        const invitation = await invRepo.findInvitationBySlug("budi-ani");

        // Test 3: listGuestsByInvitationId
        const guests = await guestRepo.listGuestsByInvitationId("invitation_dummy_1");

        // Test 4: Create a temporary guest & rsvp to verify INSERT functions
        const testGuestId = crypto.randomUUID();
        const newGuest = await guestRepo.createGuest({
          id: testGuestId,
          invitation_id: "invitation_dummy_1",
          name: "Test Guest Repositories",
          guest_code: `TEST-${Date.now()}`
        });

        const newRsvp = await rsvpRepo.createRsvp({
          invitation_id: "invitation_dummy_1",
          guest_id: testGuestId,
          guest_name: "Test Guest Repositories",
          attendance_status: "attending",
          total_guest: 2,
          message: "Congrats from repository tests!"
        });

        return new Response(
          JSON.stringify({
            status: "success",
            message: "Repository integration tests passed successfully",
            tests: {
              findUserById: user ? "passed" : "failed",
              findInvitationBySlug: invitation ? "passed" : "failed",
              listGuestsByInvitationId: guests.length > 0 ? "passed" : "failed",
              createGuest: newGuest ? "passed" : "failed",
              createRsvp: newRsvp ? "passed" : "failed"
            },
            data: {
              user,
              invitation,
              guestsCount: guests.length,
              newGuest,
              newRsvp
            }
          }),
          {
            status: 200,
            headers: {
              "Content-Type": "application/json",
              ...corsHeaders,
            }
          }
        );
      } catch (error: any) {
        return new Response(
          JSON.stringify({
            status: "error",
            message: "Repository integration tests failed",
            error: error.message || error
          }),
          {
            status: 500,
            headers: {
              "Content-Type": "application/json",
              ...corsHeaders,
            }
          }
        );
      }
    }

    // Catch all other routes
    return new Response(
      JSON.stringify({
        error: "Not Found",
      }),
      {
        status: 404,
        headers: {
          "Content-Type": "application/json",
          ...corsHeaders,
        },
      }
    );
  },
};
